154: COAP_API coap_pdu_t *
155: coap_new_pdu(coap_pdu_type_t type, coap_pdu_code_t code,
156:              coap_session_t *session) {
157:   coap_pdu_t *pdu;
158: 
159:   coap_lock_lock(session->context, return NULL);
160:   pdu = coap_new_pdu_lkd(type, code, session);
161:   coap_lock_unlock(session->context);
162:   return pdu;
163: }
164: 
165: coap_pdu_t *
166: coap_new_pdu_lkd(coap_pdu_type_t type, coap_pdu_code_t code,
167:                  coap_session_t *session) {
168:   coap_pdu_t *pdu;
169: 
170:   coap_lock_check_locked(session->context);
171:   pdu = coap_pdu_init(type, code, coap_new_message_id_lkd(session),
172:                       coap_session_max_pdu_size_lkd(session));
173:   if (!pdu)
174:     coap_log_crit("coap_new_pdu: cannot allocate memory for new PDU\n");
175:   return pdu;
176: }
177: 
178: void
179: coap_delete_pdu(coap_pdu_t *pdu) {
180:   if (pdu != NULL) {
181: #ifdef WITH_LWIP
182:     pbuf_free(pdu->pbuf);
183: #else
184:     if (pdu->token != NULL)
185:       coap_free_type(COAP_PDU_BUF, pdu->token - pdu->max_hdr_size);
186: #endif
187:     coap_free_type(COAP_PDU, pdu);
188:   }
189: }
